cd /work && python3 -c "
import csv,warnings; warnings.filterwarnings('ignore')
from pymatgen.core import Structure
rows={r['candidate_id']:r for r in csv.DictReader(open('cdft_piezo_pool.csv'))}
for cid in ['c092','c051','c029','c010','c011','c033','c078','c079','c080','c005']:
    s=Structure.from_str(rows[cid]['poscar'],fmt='poscar')
    print('==',cid,rows[cid]['formula'],'V/at %.1f'%(s.volume/len(s)))
    for i,site in enumerate(s):
        nn=s.get_neighbors(site,3.2)
        nn=sorted(nn,key=lambda n:n.nn_distance)[:4]
        print('  ',site.specie,[ (n.specie.symbol,round(n.nn_distance,2)) for n in nn])
        if i>4: break
" 2>/dev/null

